"use client";

import * as React from "react";
import { Pause, Play } from "lucide-react";
import { PromptComposer, type ComposerStatus } from "./prompt-composer";
import {
  AnswerActions,
  StreamingText,
  type AnswerSegment,
  type AnswerSource,
} from "./streaming-answer";
import { ThinkingTrace } from "./thinking-trace";
import { ToolCall, type ToolCallStatus } from "./tool-call";
import {
  WebResearch,
  type ResearchSource,
  type ResearchStatus,
} from "./web-research";

/* ─────────────────────────────────────────────────────────
 * AGENT PLAYBACK: your product, working, on a loop
 *
 *   typing     the prompt types itself into the composer, with
 *              a person's uneven rhythm
 *   sent       the text lifts out of the composer and glides
 *              into the message bubble; Send becomes a spinner
 *   working    the agent's blocks arrive one by one, each opening
 *              its own room so what's above glides up: a thinking
 *              trace ticking off steps, web research stacking
 *              sources, a tool call filling in its arguments
 *   answering  the answer streams in word by word, citations and
 *              all, then its actions settle in underneath
 *   next       a beat to read it, then the conversation dissolves
 *              and the next prompt starts typing
 *
 * Built from the real components (composer, thinking trace, web
 * research, tool call, streaming answer), so the hero shows
 * exactly what the product does. It pauses off-screen and in a
 * hidden tab, has its own pause button, and with reduced motion
 * shows the finished first conversation, still.
 * ───────────────────────────────────────────────────────── */

export type PlaybackStep =
  | {
      type: "thinking";
      steps: string[];
      label?: string;
      variant?: "steps" | "reasoning";
    }
  | { type: "search"; queries: { query: string; sources: ResearchSource[] }[] }
  | {
      type: "tool";
      name: string;
      title?: string;
      icon?: React.ReactNode;
      /** Fills in field by field, as a model writes the arguments. */
      input: Record<string, unknown>;
      output?: unknown;
      renderOutput?: (output: unknown) => React.ReactNode;
      /** How long it runs (ms); shown as its run time. */
      duration?: number;
      /** Show the arguments and result. Default true. */
      open?: boolean;
    }
  | {
      type: "answer";
      content: AnswerSegment[] | string;
      sources?: AnswerSource[];
    };

export interface PlaybackTurn {
  prompt: string;
  steps: PlaybackStep[];
}

export interface AgentPlaybackProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The conversations to play, in order. */
  turns: PlaybackTurn[];
  /** Pace: 2 plays twice as fast. */
  speed?: number;
  /** How long a finished answer stays before the next prompt (ms). */
  hold?: number;
  /** Start again after the last turn. */
  loop?: boolean;
  /** Pause from outside, e.g. while a dialog is open. */
  paused?: boolean;
  placeholder?: string;
  /** Above the conversation, e.g. your product's name. */
  header?: React.ReactNode;
  /** The window's height; it never changes, so the page around it never moves. */
  height?: number;
}

type Block =
  | {
      id: number;
      type: "thinking";
      labels: string[];
      status: "running" | "done";
      startedAt: number;
      label?: string;
      variant: "steps" | "reasoning";
    }
  | {
      id: number;
      type: "search";
      status: ResearchStatus;
      queries: string[];
      sources: ResearchSource[];
    }
  | {
      id: number;
      type: "tool";
      step: Extract<PlaybackStep, { type: "tool" }>;
      status: ToolCallStatus;
      input: Record<string, unknown>;
    }
  | {
      id: number;
      type: "answer";
      content: AnswerSegment[];
      status: "streaming" | "done";
      sources?: AnswerSource[];
    };

type View = {
  turn: number;
  draft: string;
  sent: string | null;
  composer: ComposerStatus;
  blocks: Block[];
  leaving: boolean;
};

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const EMPTY: View = {
  turn: 0,
  draft: "",
  sent: null,
  composer: "ready",
  blocks: [],
  leaving: false,
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** Words and spaces as separate tokens, citations whole, so an answer can stream a few at a time. */
function tokens(content: AnswerSegment[] | string): AnswerSegment[] {
  const parts: AnswerSegment[] =
    typeof content === "string" ? [content] : content;
  return parts.flatMap((p): AnswerSegment[] =>
    typeof p === "string" ? p.split(/(\s+)/).filter(Boolean) : [p],
  );
}

/** The finished state of a turn, for reduced motion. */
function settled(turn: PlaybackTurn, index: number): View {
  let id = 0;
  const blocks: Block[] = turn.steps.map((step) => {
    id += 1;
    if (step.type === "thinking")
      return {
        id,
        type: "thinking",
        labels: step.steps,
        status: "done",
        startedAt: 0,
        label: step.label,
        variant: step.variant ?? "steps",
      };
    if (step.type === "search")
      return {
        id,
        type: "search",
        status: "done",
        queries: step.queries.map((q) => q.query),
        sources: step.queries.flatMap((q) => q.sources),
      };
    if (step.type === "tool")
      return { id, type: "tool", step, status: "done", input: step.input };
    return {
      id,
      type: "answer",
      content: tokens(step.content),
      status: "done",
      sources: step.sources,
    };
  });
  return {
    turn: index,
    draft: "",
    sent: turn.prompt,
    composer: "ready",
    blocks,
    leaving: false,
  };
}

/**
 * A clock whose waits can be paused mid-way and resumed for the time that was left,
 * so going off-screen (or pressing pause) freezes the story exactly where it is.
 */
function createClock() {
  let paused = false;
  let wait: {
    resolve: () => void;
    left: number;
    since: number;
    timer: number;
  } | null = null;
  const start = () => {
    if (!wait) return;
    wait.since = performance.now();
    wait.timer = window.setTimeout(
      () => {
        const done = wait?.resolve;
        wait = null;
        done?.();
      },
      Math.max(0, wait.left),
    );
  };
  return {
    sleep(ms: number) {
      return new Promise<void>((resolve) => {
        wait = { resolve, left: ms, since: 0, timer: 0 };
        if (!paused) start();
      });
    },
    pause() {
      if (paused) return;
      paused = true;
      if (wait?.timer) {
        window.clearTimeout(wait.timer);
        wait.left -= performance.now() - wait.since;
        wait.timer = 0;
      }
    },
    resume() {
      if (!paused) return;
      paused = false;
      if (wait && !wait.timer) start();
    },
    stop() {
      if (wait?.timer) window.clearTimeout(wait.timer);
      wait = null;
    },
  };
}

/** A block that opens its own room as it arrives, so everything above glides up instead of jumping. */
function Arrive({
  reduced,
  children,
}: {
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [open, setOpen] = React.useState(reduced);
  React.useEffect(() => {
    if (open) return;
    const frame = requestAnimationFrame(() =>
      requestAnimationFrame(() => setOpen(true)),
    );
    return () => cancelAnimationFrame(frame);
  }, [open]);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transform: open ? "none" : "translateY(8px)",
        filter: open ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `grid-template-rows 520ms ${MORPH}, opacity 420ms ${MORPH} 80ms, transform 520ms ${MORPH}, filter 420ms ${MORPH} 80ms`,
      }}
    >
      <div className="min-h-0">{children}</div>
    </div>
  );
}

export function AgentPlayback({
  turns,
  speed = 1,
  hold = 4200,
  loop = true,
  paused = false,
  placeholder = "Ask anything",
  header,
  height = 540,
  className = "",
  ...props
}: AgentPlaybackProps) {
  const reduced = useReducedMotion();
  const [view, setView] = React.useState<View>(EMPTY);
  const [userPaused, setUserPaused] = React.useState(false);
  const [offscreen, setOffscreen] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const composerRef = React.useRef<HTMLDivElement>(null);
  const bubbleRef = React.useRef<HTMLDivElement>(null);
  const fromRect = React.useRef<DOMRect | null>(null);
  const clock = React.useMemo(createClock, []);
  const pausedAt = React.useRef<number | null>(null);
  const halted = paused || userPaused || offscreen || hidden;
  // Restart only when the script itself changes, so an inline array in a parent that re-renders is fine.
  const latest = React.useRef(turns);
  React.useLayoutEffect(() => {
    latest.current = turns;
  });
  const scriptKey = turns
    .map((t) => `${t.prompt}\u0000${t.steps.length}`)
    .join("\u0001");

  // Off-screen or in a background tab, the story waits.
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => setOffscreen(!entry.isIntersecting),
      { threshold: 0.15 },
    );
    observer.observe(el);
    const onVisibility = () => setHidden(document.visibilityState === "hidden");
    onVisibility();
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  // Pausing freezes the clock; on resume, live timers skip the time they were paused for.
  React.useEffect(() => {
    if (halted) {
      clock.pause();
      pausedAt.current ??= Date.now();
      return;
    }
    const since = pausedAt.current;
    pausedAt.current = null;
    clock.resume();
    if (since !== null) {
      const gap = Date.now() - since;
      setView((v) => ({
        ...v,
        blocks: v.blocks.map((b) =>
          b.type === "thinking" && b.status === "running"
            ? { ...b, startedAt: b.startedAt + gap }
            : b,
        ),
      }));
    }
  }, [halted, clock]);

  // The script.
  React.useEffect(() => {
    const turns = latest.current;
    if (!turns.length) return;
    if (reduced) {
      setView(settled(turns[0], 0));
      return;
    }
    let alive = true;
    let id = 0;
    const pace = (ms: number) => clock.sleep(ms / Math.max(0.1, speed));
    const update = (fn: (v: View) => View) => alive && setView(fn);
    const patch = (blockId: number, fn: (b: Block) => Block) =>
      update((v) => ({
        ...v,
        blocks: v.blocks.map((b) => (b.id === blockId ? fn(b) : b)),
      }));

    const play = async () => {
      for (let t = 0; alive; t = (t + 1) % turns.length) {
        const turn = turns[t];
        update(() => ({ ...EMPTY, turn: t }));
        await pace(700);

        // A person typing: quick runs, small pauses after words and punctuation.
        for (let i = 1; i <= turn.prompt.length && alive; i++) {
          update((v) => ({ ...v, draft: turn.prompt.slice(0, i) }));
          const ch = turn.prompt[i - 1];
          await pace(
            /[,.?!]/.test(ch)
              ? 180
              : ch === " "
                ? 70 + Math.random() * 60
                : 26 + Math.random() * 34,
          );
        }
        if (!alive) return;
        await pace(420);

        // Send: note where the text sits in the composer so the bubble can glide out of it.
        const field = composerRef.current?.querySelector("textarea");
        fromRect.current = field?.getBoundingClientRect() ?? null;
        update((v) => ({
          ...v,
          draft: "",
          sent: turn.prompt,
          composer: "submitted",
        }));
        await pace(650);

        for (const step of turn.steps) {
          if (!alive) return;
          const blockId = ++id;
          if (step.type === "thinking") {
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "thinking",
                  labels: [],
                  status: "running",
                  startedAt: Date.now(),
                  label: step.label,
                  variant: step.variant ?? "steps",
                },
              ],
            }));
            for (const label of step.steps) {
              await pace(650 + Math.random() * 350);
              patch(blockId, (b) =>
                b.type === "thinking"
                  ? { ...b, labels: [...b.labels, label] }
                  : b,
              );
            }
            await pace(900);
            patch(blockId, (b) =>
              b.type === "thinking" ? { ...b, status: "done" } : b,
            );
            await pace(700);
          } else if (step.type === "search") {
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "search",
                  status: "searching",
                  queries: [],
                  sources: [],
                },
              ],
            }));
            for (const group of step.queries) {
              patch(blockId, (b) =>
                b.type === "search"
                  ? {
                      ...b,
                      status: "searching",
                      queries: [...b.queries, group.query],
                    }
                  : b,
              );
              await pace(1150);
              for (const source of group.sources) {
                patch(blockId, (b) =>
                  b.type === "search"
                    ? {
                        ...b,
                        status: "reading",
                        sources: [...b.sources, source],
                      }
                    : b,
                );
                await pace(360 + Math.random() * 160);
              }
              await pace(300);
            }
            patch(blockId, (b) =>
              b.type === "search" ? { ...b, status: "done" } : b,
            );
            await pace(650);
          } else if (step.type === "tool") {
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "tool",
                  step,
                  status: "preparing",
                  input: {},
                },
              ],
            }));
            for (const [key, value] of Object.entries(step.input)) {
              await pace(280 + Math.random() * 140);
              patch(blockId, (b) =>
                b.type === "tool"
                  ? { ...b, input: { ...b.input, [key]: value } }
                  : b,
              );
            }
            await pace(350);
            patch(blockId, (b) =>
              b.type === "tool" ? { ...b, status: "running" } : b,
            );
            await pace(step.duration ?? 1300);
            patch(blockId, (b) =>
              b.type === "tool" ? { ...b, status: "done" } : b,
            );
            await pace(800);
          } else {
            const all = tokens(step.content);
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "answer",
                  content: [],
                  status: "streaming",
                  sources: step.sources,
                },
              ],
            }));
            await pace(250);
            for (let i = 0; i < all.length && alive;) {
              i = Math.min(all.length, i + 1 + Math.floor(Math.random() * 3));
              const shown = all.slice(0, i);
              patch(blockId, (b) =>
                b.type === "answer" ? { ...b, content: shown } : b,
              );
              await pace(38 + Math.random() * 46);
            }
            patch(blockId, (b) =>
              b.type === "answer" ? { ...b, status: "done" } : b,
            );
          }
        }
        update((v) => ({ ...v, composer: "ready" }));
        await pace(hold);
        if (!loop && t === turns.length - 1) return;
        // The conversation dissolves before the next one starts.
        update((v) => ({ ...v, leaving: true }));
        await pace(520);
      }
    };
    play();
    return () => {
      alive = false;
      clock.stop();
    };
  }, [scriptKey, speed, hold, loop, reduced, clock]);

  // The sent text glides from where it was typed into its bubble.
  React.useLayoutEffect(() => {
    const bubble = bubbleRef.current;
    const from = fromRect.current;
    fromRect.current = null;
    if (!bubble || !from || reduced) return;
    const to = bubble.getBoundingClientRect();
    const dx = from.left + 14 - (to.left + 16);
    const dy = from.top + 12 - (to.top + 10);
    bubble.animate(
      [
        {
          transform: `translate(${dx}px, ${dy}px)`,
          backgroundColor: "transparent",
        },
        {
          transform: "none",
          backgroundColor: getComputedStyle(bubble).backgroundColor,
        },
      ],
      { duration: 620, easing: MORPH },
    );
  }, [view.sent, reduced]);

  const turn = turns[view.turn];

  return (
    <div
      ref={rootRef}
      role="region"
      aria-roledescription="demo"
      aria-label="Product demo"
      className={`relative flex flex-col overflow-hidden rounded-[22px] border border-border bg-background ${className}`}
      style={{ height }}
      {...props}
    >
      {/* What the demo shows, for people who can't watch it; the moving copy is hidden from them. */}
      <p className="sr-only">
        {turn
          ? `A looping demo. Someone asks: “${turn.prompt}”, and the assistant works through it and answers.`
          : ""}
      </p>

      {header && (
        <div className="flex h-11 shrink-0 items-center border-b border-border px-4 pr-12 text-[13px] font-medium text-foreground">
          {header}
        </div>
      )}

      <button
        type="button"
        aria-label={userPaused ? "Play demo" : "Pause demo"}
        aria-pressed={userPaused}
        onClick={() => setUserPaused((p) => !p)}
        className={`cursor-pointer absolute right-2.5 top-2 z-10 flex size-7 items-center justify-center rounded-full bg-background text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:text-foreground ${FOCUS}`}
      >
        <span
          aria-hidden="true"
          className="absolute inset-0 flex items-center justify-center"
          style={swap(!userPaused, reduced)}
        >
          <Pause className="size-3" fill="currentColor" strokeWidth={0} />
        </span>
        <span
          aria-hidden="true"
          className="absolute inset-0 flex items-center justify-center"
          style={swap(userPaused, reduced)}
        >
          <Play
            className="size-3 translate-x-px"
            fill="currentColor"
            strokeWidth={0}
          />
        </span>
      </button>

      <div aria-hidden="true" inert className="flex min-h-0 flex-1 flex-col">
        {/* The conversation sits on the composer and grows upwards; older lines fade out at the top. */}
        <div className="relative min-h-0 flex-1 overflow-hidden [mask-image:linear-gradient(to_bottom,transparent,#000_56px)]">
          <div
            key={view.turn}
            className="absolute inset-x-0 bottom-0 flex flex-col gap-4 px-4 pb-4 sm:px-5"
            style={{
              opacity: view.leaving ? 0 : 1,
              filter: view.leaving ? "blur(6px)" : "none",
              transform: view.leaving ? "translateY(-12px)" : "none",
              transition: reduced
                ? "none"
                : `opacity 480ms ${MORPH}, filter 480ms ${MORPH}, transform 520ms ${MORPH}`,
            }}
          >
            {view.sent && (
              // Not wrapped in Arrive: its own glide out of the composer is the entrance.
              <div className="flex justify-end">
                <div
                  ref={bubbleRef}
                  className="max-w-[85%] whitespace-pre-wrap rounded-[20px] bg-muted px-4 py-2.5 text-[14px] leading-relaxed text-foreground"
                >
                  {view.sent}
                </div>
              </div>
            )}
            {view.blocks.map((b) => (
              <Arrive key={b.id} reduced={reduced}>
                {b.type === "thinking" ? (
                  <ThinkingTrace
                    variant={b.variant}
                    status={b.status}
                    label={b.label}
                    startedAt={reduced ? undefined : b.startedAt}
                    steps={b.labels.map((label) => ({ label }))}
                  />
                ) : b.type === "search" ? (
                  <WebResearch
                    status={b.status}
                    queries={b.queries}
                    sources={b.sources}
                  />
                ) : b.type === "tool" ? (
                  <ToolCall
                    name={b.step.name}
                    title={b.step.title}
                    icon={b.step.icon}
                    status={b.status}
                    input={b.input}
                    output={b.status === "done" ? b.step.output : undefined}
                    renderOutput={b.step.renderOutput}
                    duration={b.step.duration ?? 1300}
                    defaultOpen={b.step.open ?? true}
                  />
                ) : (
                  <div className="flex flex-col gap-2">
                    <StreamingText
                      content={b.content}
                      status={b.status}
                      className="text-[14px]"
                    />
                    <div
                      className="grid"
                      style={{
                        gridTemplateRows: b.status === "done" ? "1fr" : "0fr",
                        opacity: b.status === "done" ? 1 : 0,
                        transition: reduced
                          ? "none"
                          : `grid-template-rows 420ms ${MORPH}, opacity 360ms ${MORPH} 120ms`,
                      }}
                    >
                      <div className="min-h-0 overflow-hidden">
                        <AnswerActions copyText="" sources={b.sources} />
                      </div>
                    </div>
                  </div>
                )}
              </Arrive>
            ))}
          </div>
        </div>

        <div ref={composerRef} className="shrink-0 px-3 pb-3">
          <PromptComposer
            value={view.draft}
            status={view.composer}
            placeholder={placeholder}
            onSubmit={() => {}}
            onStop={() => {}}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { ArrowUp, Paperclip, Square } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PROMPT COMPOSER: where the conversation starts
 *
 *   ready      type; Enter sends, Shift+Enter adds a line
 *   submitted  sent: the arrow blurs into a spinner
 *   streaming  the spinner blurs into Stop
 *   error      ready to try again
 *   disabled   with a reason, e.g. a rate limit, folding open
 *              above the field
 *
 * Near the limit a counter opens in and rolls as you type;
 * attachments fold open above the field as the first one lands.
 *
 * status takes useChat's status as is. Files come in through the
 * paperclip, paste or drag and drop; render them as chips in the
 * attachments slot. The toolbar slot fits a mode switcher.
 * ───────────────────────────────────────────────────────── */

export type ComposerStatus = "ready" | "submitted" | "streaming" | "error";

export interface PromptComposerProps extends Omit<
  React.FormHTMLAttributes<HTMLFormElement>,
  "onSubmit" | "defaultValue"
> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmit: (value: string) => void;
  onStop?: () => void;
  /** Pass useChat's status straight through. */
  status?: ComposerStatus;
  placeholder?: string;
  disabled?: boolean;
  /** Shown above the input while disabled, e.g. "You've reached today's limit." */
  disabledReason?: React.ReactNode;
  /** Enables the paperclip, paste and drop. */
  onFilesSelected?: (files: File[]) => void;
  accept?: string;
  /** Attachment chips, shown above the text. */
  attachments?: React.ReactNode;
  /** Controls at the bottom left, e.g. a mode switcher. */
  toolbar?: React.ReactNode;
  maxLength?: number;
  /** Allow sending with no text, e.g. when files are attached. */
  allowEmpty?: boolean;
  autoFocus?: boolean;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A block that folds open to its height and shut again, keeping what it showed while it closes. */
function Fold({
  show,
  reduced,
  children,
}: {
  show: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [last, setLast] = React.useState(children);
  if (show && children !== last) setLast(children);
  return (
    <div
      aria-hidden={!show || undefined}
      inert={!show}
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${MORPH}, opacity ${show ? "280ms" : "140ms"} ${MORPH}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{show ? children : last}</div>
    </div>
  );
}

export function PromptComposer({
  value,
  defaultValue = "",
  onValueChange,
  onSubmit,
  onStop,
  status = "ready",
  placeholder = "Ask anything",
  disabled = false,
  disabledReason,
  onFilesSelected,
  accept,
  attachments,
  toolbar,
  maxLength,
  allowEmpty = false,
  autoFocus,
  className = "",
  ...props
}: PromptComposerProps) {
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const [dragging, setDragging] = React.useState(false);
  const text = value ?? own;
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const fileRef = React.useRef<HTMLInputElement>(null);
  const busy = status === "submitted" || status === "streaming";
  const canSend =
    !disabled &&
    !busy &&
    (allowEmpty || text.trim().length > 0) &&
    (maxLength === undefined || text.length <= maxLength);

  const setText = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  // Grow with the text, up to a scrolling maximum.
  React.useLayoutEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 200)}px`;
  }, [text]);

  const submit = () => {
    if (!canSend) return;
    onSubmit(text);
    if (value === undefined) setOwn("");
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      submit();
    }
  };

  const takeFiles = (list: FileList | null) => {
    if (!list || list.length === 0 || !onFilesSelected) return false;
    onFilesSelected(Array.from(list));
    return true;
  };

  const action = busy
    ? status === "streaming" && onStop
      ? "stop"
      : "wait"
    : "send";

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit();
      }}
      onDragOver={(e) => {
        if (!onFilesSelected || !e.dataTransfer.types.includes("Files")) return;
        e.preventDefault();
        setDragging(true);
      }}
      onDragLeave={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node))
          setDragging(false);
      }}
      onDrop={(e) => {
        if (!onFilesSelected) return;
        e.preventDefault();
        setDragging(false);
        takeFiles(e.dataTransfer.files);
      }}
      className={`relative rounded-2xl border bg-background transition-colors focus-within:border-foreground/25 ${
        dragging ? "border-dashed border-foreground/40" : "border-border"
      } ${className}`}
      {...props}
    >
      <Fold show={Boolean(disabled && disabledReason)} reduced={reduced}>
        <div className="border-b border-border px-3.5 py-2 text-[12px] text-muted-foreground">
          {disabledReason}
        </div>
      </Fold>

      <Fold show={Boolean(attachments)} reduced={reduced}>
        <div className="flex flex-wrap gap-2 px-3 pt-3">{attachments}</div>
      </Fold>

      <textarea
        ref={textareaRef}
        rows={1}
        value={text}
        autoFocus={autoFocus}
        disabled={disabled}
        placeholder={placeholder}
        aria-label={placeholder}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={onKeyDown}
        onPaste={(e) => {
          if (
            takeFiles(e.clipboardData.files) &&
            !e.clipboardData.getData("text")
          )
            e.preventDefault();
        }}
        className="block max-h-[200px] w-full resize-none overflow-y-auto bg-transparent px-3.5 pb-1 pt-3 text-[14px] leading-6 text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-60"
      />

      <div className="flex items-center gap-1.5 px-2 pb-2 pt-1">
        {onFilesSelected && (
          <>
            <button
              type="button"
              aria-label="Attach files"
              disabled={disabled}
              onClick={() => fileRef.current?.click()}
              className={`cursor-pointer disabled:cursor-default flex size-8 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-40 ${FOCUS}`}
            >
              <Paperclip className="size-4" />
            </button>
            <input
              ref={fileRef}
              type="file"
              multiple
              accept={accept}
              className="hidden"
              onChange={(e) => {
                takeFiles(e.target.files);
                e.target.value = "";
              }}
            />
          </>
        )}
        {toolbar}

        <div className="ml-auto flex items-center gap-2.5">
          {maxLength !== undefined && (
            // Opens in near the limit and rolls as you type; red once you're over.
            <span
              aria-hidden={text.length <= maxLength * 0.8 || undefined}
              className="grid"
              style={{
                gridTemplateColumns:
                  text.length > maxLength * 0.8 ? "1fr" : "0fr",
                opacity: text.length > maxLength * 0.8 ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 380ms ${MORPH}, opacity 260ms ${MORPH}`,
              }}
            >
              <span
                className={`flex min-w-0 items-baseline overflow-hidden whitespace-nowrap font-mono text-[11px] tabular-nums transition-colors duration-300 ${
                  text.length > maxLength
                    ? "text-red-500"
                    : "text-muted-foreground"
                }`}
              >
                <NumberRoll value={text.length} duration={300} />/{maxLength}
              </span>
            </span>
          )}
          <button
            type={action === "send" ? "submit" : "button"}
            aria-label={
              action === "stop"
                ? "Stop"
                : action === "wait"
                  ? "Sending"
                  : "Send"
            }
            disabled={action === "send" ? !canSend : action === "wait"}
            onClick={action === "stop" ? onStop : undefined}
            className={`cursor-pointer disabled:cursor-default relative flex size-8 items-center justify-center rounded-full bg-primary text-primary-foreground transition-[opacity,transform] duration-200 active:scale-95 disabled:opacity-35 ${FOCUS}`}
          >
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(action === "send", reduced)}
            >
              <ArrowUp className="size-4" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(action === "stop", reduced)}
            >
              <Square fill="currentColor" className="size-3" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(action === "wait", reduced)}
            >
              {/* Spins only while it's showing. */}
              <span
                className={`size-3.5 rounded-full border-[1.5px] border-current/35 border-t-current motion-reduce:animate-none ${action === "wait" ? "animate-spin" : ""}`}
              />
            </span>
          </button>
        </div>
      </div>

      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 flex items-center justify-center rounded-2xl bg-background/85 text-[13px] font-medium text-foreground"
        style={{
          opacity: dragging ? 1 : 0,
          transition: reduced ? "none" : `opacity 200ms ${MORPH}`,
        }}
      >
        Drop files to attach
      </div>
    </form>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import {
  AlertCircle,
  Copy,
  RotateCcw,
  ThumbsDown,
  ThumbsUp,
} from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STREAMING ANSWER: an AI answer as it arrives
 *
 *   StreamingText   the text so far, with inline citation chips;
 *                   only newly arrived words fade in
 *   AnswerActions   copy (blurs into a check that draws itself),
 *                   regenerate, feedback (the thumb fills with a
 *                   small thrown pop) and a sources stack whose
 *                   count rolls
 *   FollowUps       suggested next questions
 *
 * StreamingText renders whatever you pass it: append to `content`
 * as tokens arrive. Blank lines start new paragraphs, and finished
 * paragraphs don't re-render while the last one grows. For Markdown,
 * pass your renderer as children instead of `content`.
 * ───────────────────────────────────────────────────────── */

export type AnswerCitation = { type: "citation"; label: string; href?: string };
export type AnswerSegment = string | AnswerCitation;
export type AnswerStatus = "streaming" | "done" | "stopped" | "error";
export type AnswerFeedback = "up" | "down" | null;

export interface AnswerSource {
  name: string;
  href?: string;
  /** A favicon or logo, e.g. <img src="…/favicon.ico" alt="" />. */
  icon?: React.ReactNode;
  /** Tailwind background class for the dot when there's no icon. */
  color?: string;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const DOTS = [
  "bg-blue-500",
  "bg-emerald-500",
  "bg-orange-500",
  "bg-violet-500",
];
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/* ── StreamingText ───────────────────────────────────────── */

export interface StreamingTextProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "content"
> {
  /** The answer so far. Append as tokens arrive. */
  content?: AnswerSegment[];
  status?: AnswerStatus;
  /** Shows a retry button when status is "error". */
  onRetry?: () => void;
  /** Your own renderer (e.g. Markdown) instead of `content`. */
  children?: React.ReactNode;
}

type Token =
  | { kind: "word" | "space"; text: string }
  | { kind: "cite"; citation: AnswerCitation };

function toParagraphs(content: AnswerSegment[]): Token[][] {
  const paragraphs: Token[][] = [[]];
  for (const segment of content) {
    if (typeof segment !== "string") {
      paragraphs[paragraphs.length - 1].push({
        kind: "cite",
        citation: segment,
      });
      continue;
    }
    for (const part of segment.split(/(\n{2,})/)) {
      if (/^\n{2,}$/.test(part)) {
        paragraphs.push([]);
        continue;
      }
      for (const text of part.split(/(\s+)/)) {
        if (text)
          paragraphs[paragraphs.length - 1].push({
            kind: /^\s+$/.test(text) ? "space" : "word",
            text,
          });
      }
    }
  }
  return paragraphs.filter(
    (p, i) => p.length > 0 || i === paragraphs.length - 1,
  );
}

function CitationChip({ citation }: { citation: AnswerCitation }) {
  const className = `mx-0.5 inline-flex -translate-y-px items-center gap-1 rounded-[5px] border border-border bg-muted px-1.5 py-px align-middle font-mono text-[11px] text-foreground animate-[ui-fade-up_240ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none ${FOCUS}`;
  const inner = (
    <>
      <span
        aria-hidden="true"
        className="size-1.5 shrink-0 rounded-full bg-emerald-500"
      />
      {citation.label}
    </>
  );
  return citation.href ? (
    <a
      href={citation.href}
      target="_blank"
      rel="noreferrer"
      className={`${className} transition-colors hover:bg-accent`}
    >
      {inner}
    </a>
  ) : (
    <span className={className}>{inner}</span>
  );
}

const Caret = () => (
  <span
    aria-hidden="true"
    className="ml-0.5 inline-block h-[1.05em] w-[2px] translate-y-[0.18em] bg-foreground animate-[ui-blink_1s_steps(2,start)_infinite] motion-reduce:animate-none"
  />
);

// Words keep a stable key by position, so only words that just arrived mount and fade in.
const Paragraph = React.memo(
  function Paragraph({
    tokens,
    caret,
  }: {
    tokens: Token[];
    signature: string;
    caret: boolean;
  }) {
    return (
      <p>
        {tokens.map((token, i) =>
          token.kind === "cite" ? (
            <CitationChip key={i} citation={token.citation} />
          ) : token.kind === "space" ? (
            token.text
          ) : (
            <span
              key={i}
              className="animate-[ui-fade-in_420ms_ease-out_both] motion-reduce:animate-none"
            >
              {token.text}
            </span>
          ),
        )}
        {caret && <Caret />}
      </p>
    );
  },
  (a, b) => a.signature === b.signature && a.caret === b.caret,
);

export function StreamingText({
  content = [],
  status = "done",
  onRetry,
  children,
  className = "",
  ...props
}: StreamingTextProps) {
  const streaming = status === "streaming";
  const paragraphs = children === undefined ? toParagraphs(content) : [];

  return (
    <div
      aria-busy={streaming}
      className={`flex flex-col gap-3 text-[13.5px] leading-relaxed text-foreground ${className}`}
      {...props}
    >
      {children ??
        paragraphs.map((tokens, i) => (
          <Paragraph
            key={i}
            tokens={tokens}
            signature={tokens
              .map((t) =>
                t.kind === "cite" ? `\u0000${t.citation.label}` : t.text,
              )
              .join("")}
            caret={streaming && i === paragraphs.length - 1}
          />
        ))}

      {status === "stopped" && (
        <p className="text-xs text-muted-foreground animate-[ui-fade-in_300ms_ease-out_both]">
          Stopped
        </p>
      )}

      {status === "error" && (
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground animate-[ui-fade-in_300ms_ease-out_both]">
          <AlertCircle
            aria-hidden="true"
            className="size-3.5 shrink-0 text-red-500"
          />
          The answer was interrupted.
          {onRetry && (
            <button
              type="button"
              onClick={onRetry}
              className={`cursor-pointer rounded px-1 font-medium text-foreground underline decoration-border underline-offset-2 hover:decoration-foreground ${FOCUS}`}
            >
              Retry
            </button>
          )}
        </p>
      )}
    </div>
  );
}

/* ── AnswerActions ───────────────────────────────────────── */

export interface AnswerActionsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Text the copy button puts on the clipboard. Hides the button when omitted. */
  copyText?: string;
  onRegenerate?: () => void;
  /** Controlled feedback, e.g. restored from your database. */
  feedback?: AnswerFeedback;
  defaultFeedback?: AnswerFeedback;
  onFeedback?: (value: AnswerFeedback) => void;
  sources?: AnswerSource[];
  onSourcesClick?: () => void;
  /** Disables the buttons, e.g. while the answer is still streaming. */
  disabled?: boolean;
}

function IconButton({
  label,
  pressed,
  disabled,
  onClick,
  children,
}: {
  label: string;
  pressed?: boolean;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={pressed}
      disabled={disabled}
      onClick={onClick}
      className={`cursor-pointer disabled:cursor-default relative flex size-7 items-center justify-center rounded-md transition-colors duration-150 hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 ${
        pressed ? "bg-accent text-foreground" : "text-muted-foreground"
      } ${FOCUS}`}
    >
      {children}
    </button>
  );
}

/** A thumb that fills in with a small thrown pop when chosen, and empties when let go. */
function Thumb({
  down,
  filled,
  reduced,
}: {
  down?: boolean;
  filled: boolean;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (!filled || reduced) return;
    ref.current?.animate(
      [{ transform: "scale(0.8) rotate(-8deg)" }, { transform: "none" }],
      { duration: 420, easing: THROW },
    );
  }, [filled, reduced]);
  const Icon = down ? ThumbsDown : ThumbsUp;
  return (
    <span ref={ref} className="flex">
      <Icon
        className="size-3.5"
        style={{
          fill: filled ? "currentColor" : "transparent",
          transition: reduced ? "none" : `fill 220ms ${MORPH}`,
        }}
      />
    </span>
  );
}

export function AnswerActions({
  copyText,
  onRegenerate,
  feedback,
  defaultFeedback = null,
  onFeedback,
  sources,
  onSourcesClick,
  disabled,
  className = "",
  ...props
}: AnswerActionsProps) {
  const reduced = useReducedMotion();
  const [copied, setCopied] = React.useState(false);
  const [ownFeedback, setOwnFeedback] =
    React.useState<AnswerFeedback>(defaultFeedback);
  const current = feedback !== undefined ? feedback : ownFeedback;

  React.useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 1600);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    if (!copyText) return;
    try {
      await navigator.clipboard.writeText(copyText);
      setCopied(true);
    } catch {
      // Clipboard can be blocked by the browser; nothing to undo.
    }
  };

  const rate = (value: "up" | "down") => {
    const next = current === value ? null : value;
    if (feedback === undefined) setOwnFeedback(next);
    onFeedback?.(next);
  };

  const stack = sources && sources.length > 0 && (
    <>
      <span className="flex items-center -space-x-1.5" aria-hidden="true">
        {sources.slice(0, 3).map((s, i) =>
          s.icon ? (
            <span
              key={s.name}
              className="flex size-3.5 items-center justify-center overflow-hidden rounded-full bg-background ring-2 ring-background"
            >
              {s.icon}
            </span>
          ) : (
            <span
              key={s.name}
              className={`size-3.5 rounded-full ring-2 ring-background ${s.color ?? DOTS[i % DOTS.length]}`}
            />
          ),
        )}
      </span>
      <span className="inline-flex items-baseline gap-[0.3em] tabular-nums">
        <NumberRoll value={sources.length} duration={600} />
        {sources.length === 1 ? "source" : "sources"}
      </span>
    </>
  );

  return (
    <div
      className={`flex items-center justify-between gap-4 ${className}`}
      {...props}
    >
      <div className="flex items-center gap-1">
        {copyText !== undefined && (
          <IconButton label="Copy answer" disabled={disabled} onClick={copy}>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(!copied, reduced)}
            >
              <Copy className="size-3.5" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
              style={swap(copied, reduced)}
            >
              <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                <path
                  d="M3.5 8.5 6.5 11.5 12.5 4.5"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={1}
                  style={{
                    strokeDashoffset: copied ? 0 : 1,
                    transition:
                      copied && !reduced
                        ? `stroke-dashoffset 380ms ${MORPH} 100ms`
                        : "none",
                  }}
                />
              </svg>
            </span>
          </IconButton>
        )}
        {onRegenerate && (
          <IconButton
            label="Regenerate"
            disabled={disabled}
            onClick={onRegenerate}
          >
            <RotateCcw className="size-3.5" />
          </IconButton>
        )}
        <IconButton
          label="Helpful"
          pressed={current === "up"}
          disabled={disabled}
          onClick={() => rate("up")}
        >
          <Thumb filled={current === "up"} reduced={reduced} />
        </IconButton>
        <IconButton
          label="Not helpful"
          pressed={current === "down"}
          disabled={disabled}
          onClick={() => rate("down")}
        >
          <Thumb down filled={current === "down"} reduced={reduced} />
        </IconButton>
      </div>
      {/* Outside the buttons, so their names stay their labels. */}
      <span role="status" className="sr-only">
        {copied ? "Copied" : ""}
      </span>

      {stack &&
        (onSourcesClick ? (
          <button
            type="button"
            onClick={onSourcesClick}
            className={`cursor-pointer flex items-center gap-1.5 rounded-md px-1.5 py-1 text-[11.5px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            {stack}
          </button>
        ) : (
          <span className="flex items-center gap-1.5 text-[11.5px] font-medium text-muted-foreground">
            {stack}
          </span>
        ))}
    </div>
  );
}

