"use client";

import * as React from "react";
import {
  AlertCircle,
  ChevronDown,
  CircleSlash,
  Globe,
  Search,
  Sparkle,
  X,
} from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * THINKING TRACE: an expandable record of what an agent did
 *
 *   steps      a checklist: spinner on the live step, which blurs
 *              into a check that draws itself when it's done
 *   reasoning  sentences of reasoning
 *   search     the query, then the sources read
 *   tools      tool calls: reads, edits with +/− counts, commands
 *
 * The header never swaps: "Thinking 6s" morphs into "Thought for
 * 6s" (the seconds roll as they pass), "Searching the web" into
 * "Searched the web", the sparkle into an alert on error. The
 * list eases taller as steps arrive.
 *
 * Drive it from your stream: pass the steps you have so far and a
 * status. It opens while running, folds away once done (stays open
 * on error so the failure is visible), and can always be reopened.
 * ───────────────────────────────────────────────────────── */

export type ThinkingVariant = "steps" | "reasoning" | "search" | "tools";
export type ThinkingStatus = "running" | "done" | "error" | "cancelled";
export type ThinkingStepStatus = "pending" | "running" | "done" | "error";

export interface ThinkingStep {
  /** A step, a sentence of reasoning, a source title or a tool name. */
  label: string;
  /** Supporting text: a count, a domain or a file path. */
  detail?: string;
  /** Makes the row a link, e.g. a search source. */
  href?: string;
  /** Replaces the row's default mark, e.g. a site favicon. */
  icon?: React.ReactNode;
  /** Defaults to "running" for the last step while running, "done" otherwise. */
  status?: ThinkingStepStatus;
  /** Lines added and removed, for edit tool calls. */
  additions?: number;
  deletions?: number;
}

export interface ThinkingTraceProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  steps: ThinkingStep[];
  variant?: ThinkingVariant;
  status?: ThinkingStatus;
  /** Header while running. Defaults per variant, e.g. "Searching the web". */
  label?: string;
  /** Header once settled. Defaults to e.g. "Thought for 6s" when timing is known. */
  doneLabel?: string;
  /** When the work started (ms). Shows a live timer and times the done label. */
  startedAt?: number;
  /** How long it took (ms), if your stream reports it. */
  duration?: number;
  /** The search query, shown above the sources. */
  query?: string;
  /** Items not listed, shown as "+N more". */
  more?: number;
  /** Replaces the sparkle in the header. */
  icon?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Makes rows without an href clickable, e.g. to show a tool's output. */
  onStepClick?: (step: ThinkingStep, index: number) => void;
}

const RUNNING_LABEL: Record<ThinkingVariant, string> = {
  steps: "Thinking",
  reasoning: "Thinking",
  search: "Searching the web",
  tools: "Running tools",
};

const SOURCE_TONES = [
  "bg-blue-600",
  "bg-orange-500",
  "bg-emerald-600",
  "bg-violet-600",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ROW = "flex min-h-7 w-full gap-2 rounded-md px-1.5 py-0.5 text-left";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const TWO_DIGITS = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 420ms ${MORPH}, opacity ${show ? "300ms" : "160ms"} ${MORPH}, filter 300ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_0)]">
        {children}
      </span>
    </span>
  );
}

/** Seconds that roll up as they pass; minutes slide open at the first minute. */
function Elapsed({ ms, reduced }: { ms: number; reduced: boolean }) {
  const total = Math.max(0, Math.round(ms / 1000));
  const minutes = Math.floor(total / 60);
  return (
    <span className="inline-flex items-baseline">
      <Reveal show={minutes > 0} reduced={reduced}>
        <NumberRoll value={minutes} suffix="m" duration={500} />
        &nbsp;
      </Reveal>
      <NumberRoll
        value={minutes ? total % 60 : total}
        format={minutes ? TWO_DIGITS : undefined}
        suffix="s"
        direction="up"
        duration={500}
      />
    </span>
  );
}

function StepCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${MORPH} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function toneFor(key: string) {
  let hash = 0;
  for (let i = 0; i < key.length; i++)
    hash = (hash * 31 + key.charCodeAt(i)) | 0;
  return SOURCE_TONES[Math.abs(hash) % SOURCE_TONES.length];
}

function formatDuration(ms: number) {
  const s = Math.max(0, Math.round(ms / 1000));
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`;
}

/** Spins only while it's showing, so a faded-out spinner never keeps the page busy. */
function Spinner({ spinning = true }: { spinning?: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={`size-3 shrink-0 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${spinning ? "animate-spin" : ""}`}
    />
  );
}

export function ThinkingTrace({
  steps,
  variant = "steps",
  status = "done",
  label,
  doneLabel,
  startedAt,
  duration,
  query,
  more,
  icon,
  open,
  defaultOpen,
  onOpenChange,
  onStepClick,
  className = "",
  ...props
}: ThinkingTraceProps) {
  const reduced = useReducedMotion();
  const running = status === "running";
  const [autoOpen, setAutoOpen] = React.useState(running);
  const [userOpen, setUserOpen] = React.useState<boolean | undefined>(
    defaultOpen,
  );
  const expanded = open ?? userOpen ?? autoOpen;
  const panelId = React.useId();
  // Rows present on first render stagger in; rows streamed in later appear as they arrive.
  // The steps already there on mount cascade in; ones that arrive later just appear in turn.
  const [initialCount] = React.useState(steps.length);
  const listRef = React.useRef<HTMLDivElement>(null);
  const [listHeight, setListHeight] = React.useState<number | null>(null);

  // The panel takes the height of its list, so each new step eases it taller instead of jumping.
  React.useLayoutEffect(() => {
    const el = listRef.current;
    if (!el) return;
    const measure = () =>
      setListHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Live timer while running; remember when it settled so the done label can say how long it took.
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [endedAt, setEndedAt] = React.useState<number | undefined>(undefined);
  if (running && endedAt !== undefined) setEndedAt(undefined);
  React.useEffect(() => {
    if (!running) {
      if (endedAt !== undefined) return;
      const frame = requestAnimationFrame(() => setEndedAt(Date.now()));
      return () => cancelAnimationFrame(frame);
    }
    if (startedAt === undefined) return;
    const first = window.setTimeout(() => setNow(Date.now()), 0);
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(timer);
    };
  }, [running, startedAt, endedAt]);

  // Open while working; fold away after it settles, except on error so the failure stays visible.
  if ((running || status === "error") && !autoOpen) setAutoOpen(true);
  React.useEffect(() => {
    if (running || status === "error") return;
    const timer = window.setTimeout(() => setAutoOpen(false), 900);
    return () => window.clearTimeout(timer);
  }, [running, status]);

  const toggle = () => {
    const next = !expanded;
    if (open === undefined) setUserOpen(next);
    onOpenChange?.(next);
  };

  const took =
    duration ??
    (startedAt !== undefined && endedAt !== undefined
      ? endedAt - startedAt
      : undefined);
  // "Thought for" keeps the timer beside it, so the seconds that ran become the answer.
  const timed =
    status === "done" &&
    !doneLabel &&
    (variant === "steps" || variant === "reasoning") &&
    took !== undefined;
  const settledLabel =
    status === "error"
      ? "Couldn’t finish"
      : status === "cancelled"
        ? "Stopped"
        : variant === "search"
          ? "Searched the web"
          : variant === "tools"
            ? `Ran ${steps.length} ${steps.length === 1 ? "tool" : "tools"}`
            : timed
              ? "Thought for"
              : "Thought it through";
  const text = running
    ? (label ?? RUNNING_LABEL[variant])
    : (doneLabel ?? settledLabel);
  const showTime = (running && startedAt !== undefined) || timed;
  const time = running ? now - (startedAt ?? now) : (took ?? 0);
  const spoken = running
    ? text
    : timed
      ? `${text} ${formatDuration(time)}`
      : text;

  const headerIcons: Record<
    "sparkle" | "error" | "cancelled",
    React.ReactNode
  > = {
    sparkle: <Sparkle className="size-4" fill="currentColor" strokeWidth={0} />,
    error: <AlertCircle className="size-4 text-red-500" />,
    cancelled: <CircleSlash className="size-4" />,
  };
  const headerKey =
    status === "error"
      ? "error"
      : status === "cancelled"
        ? "cancelled"
        : "sparkle";

  return (
    <div className={`flex w-full flex-col ${className}`} {...props}>
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={panelId}
        onClick={toggle}
        className={`cursor-pointer -mx-1.5 flex w-fit max-w-full items-center gap-2 rounded-lg px-1.5 py-1 text-[13px] font-medium transition-colors duration-100 hover:bg-accent ${FOCUS}`}
      >
        <span
          aria-hidden="true"
          className={`relative flex size-4 shrink-0 transition-colors duration-200 ${running ? "text-foreground/70" : "text-muted-foreground"}`}
        >
          {icon ??
            (Object.keys(headerIcons) as (keyof typeof headerIcons)[]).map(
              (k) => (
                <span
                  key={k}
                  className="absolute inset-0 flex items-center justify-center"
                  style={swap(k === headerKey, reduced)}
                >
                  {headerIcons[k]}
                </span>
              ),
            )}
        </span>
        <span className="flex min-w-0 items-baseline">
          <span
            className={`min-w-0 truncate transition-colors duration-300 ${running ? SHEEN : "text-foreground/75"}`}
          >
            <TextMorph>{text}</TextMorph>
          </span>
          {(startedAt !== undefined || duration !== undefined) && (
            <Reveal show={showTime} reduced={reduced} className="shrink-0">
              <span className="pl-1.5 text-[12.5px] font-normal tabular-nums text-muted-foreground">
                <Elapsed ms={time} reduced={reduced} />
              </span>
            </Reveal>
          )}
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none ${expanded ? "rotate-180" : ""}`}
        />
      </button>
      {/* Outside the button, so its name stays its label. Never the ticking timer. */}
      <span role="status" aria-live="polite" className="sr-only">
        {spoken}
      </span>

      <div
        id={panelId}
        inert={!expanded}
        className="overflow-hidden"
        style={{
          height: expanded ? (listHeight ?? "auto") : 0,
          opacity: expanded ? 1 : 0,
          transition:
            reduced || listHeight === null
              ? "none"
              : `height 420ms ${MORPH}, opacity 320ms ${MORPH}`,
        }}
      >
        <div ref={listRef}>
          <div className="relative ml-[5px] mt-1 pl-4">
            <span
              aria-hidden="true"
              className="absolute bottom-1.5 left-[3px] top-0 w-px bg-border"
            />
            <ul className="flex flex-col gap-0.5 py-1">
              {query && (
                <li className="flex h-7 items-center gap-2 px-1.5 text-[12.5px] text-muted-foreground animate-[ui-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
                  <Search className="size-3.5 shrink-0" aria-hidden="true" />
                  <span className="truncate">{query}</span>
                </li>
              )}

              {steps.map((step, i) => {
                const last = i === steps.length - 1;
                const stepStatus: ThinkingStepStatus =
                  step.status ??
                  (last && running
                    ? "running"
                    : last && status === "error"
                      ? "error"
                      : "done");
                const failed = stepStatus === "error";
                const pending = stepStatus === "pending";
                const align =
                  variant === "reasoning" ? "items-start" : "items-center";

                const mark =
                  variant === "steps" ? (
                    // Every mark is there at once; the one for this step's status shows, and they trade places through a blur.
                    <span
                      aria-hidden="true"
                      className={`relative flex size-3.5 shrink-0 items-center justify-center ${align === "items-start" ? "mt-px" : ""}`}
                    >
                      <span
                        className="absolute inset-0 flex items-center justify-center"
                        style={swap(pending, reduced)}
                      >
                        <span className="size-3 rounded-full border-[1.5px] border-border" />
                      </span>
                      <span
                        className="absolute inset-0 flex items-center justify-center"
                        style={swap(stepStatus === "running", reduced)}
                      >
                        <Spinner spinning={stepStatus === "running"} />
                      </span>
                      <span
                        className="absolute inset-0 flex items-center justify-center text-muted-foreground"
                        style={swap(stepStatus === "done", reduced)}
                      >
                        <StepCheck
                          drawn={stepStatus === "done"}
                          reduced={reduced}
                        />
                      </span>
                      <span
                        className="absolute inset-0 flex items-center justify-center text-red-500"
                        style={swap(failed, reduced)}
                      >
                        <X className="size-3.5" strokeWidth={2.5} />
                      </span>
                    </span>
                  ) : variant === "search" ? (
                    step.icon ? (
                      <span
                        aria-hidden="true"
                        className="flex size-3.5 shrink-0 items-center justify-center overflow-hidden rounded-full"
                      >
                        {step.icon}
                      </span>
                    ) : (
                      <span
                        aria-hidden="true"
                        className={`flex size-3.5 shrink-0 items-center justify-center rounded-full text-white ${failed ? "bg-muted-foreground/40" : toneFor(step.detail ?? step.label)}`}
                      >
                        <Globe className="size-[9px]" strokeWidth={2.5} />
                      </span>
                    )
                  ) : null;

                const trailing =
                  variant === "search" || variant === "tools" ? (
                    <span className="ml-auto flex shrink-0 items-center pl-2">
                      <span
                        className="flex justify-end overflow-hidden"
                        style={{
                          width: stepStatus === "running" ? 12 : 0,
                          ...swap(stepStatus === "running", reduced),
                          transition: reduced
                            ? "none"
                            : `width 380ms ${MORPH}, opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
                        }}
                      >
                        <Spinner spinning={stepStatus === "running"} />
                      </span>
                      <Reveal show={failed} reduced={reduced}>
                        <span className="text-[11.5px] font-medium text-red-500">
                          Failed
                        </span>
                      </Reveal>
                    </span>
                  ) : null;

                const content = (
                  <>
                    {mark}
                    {variant === "tools" ? (
                      <>
                        <span
                          className={`shrink-0 text-[12.5px] font-medium ${pending ? "text-muted-foreground" : "text-foreground"}`}
                        >
                          {step.label}
                        </span>
                        {step.detail && (
                          <span className="min-w-0 truncate font-mono text-[11.5px] text-muted-foreground">
                            {step.detail}
                          </span>
                        )}
                      </>
                    ) : (
                      <>
                        <span
                          className={
                            variant === "reasoning"
                              ? "text-[12.5px] leading-relaxed text-muted-foreground"
                              : `min-w-0 truncate text-[12.5px] font-medium ${pending ? "text-muted-foreground" : "text-foreground"}`
                          }
                        >
                          {step.label}
                        </span>
                        {step.detail && (
                          <span className="shrink-0 text-[11.5px] text-muted-foreground">
                            {step.detail}
                          </span>
                        )}
                      </>
                    )}
                    {step.additions !== undefined && (
                      <span className="shrink-0 font-mono text-[11px] tabular-nums">
                        <span className="text-emerald-600">
                          +{step.additions}
                        </span>{" "}
                        <span className="text-red-500">
                          −{step.deletions ?? 0}
                        </span>
                      </span>
                    )}
                    {trailing}
                  </>
                );
                const delay = i < initialCount ? i * 90 : 0;

                return (
                  <li
                    key={`${i}-${step.label}`}
                    className="animate-[ui-fade-up_320ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none"
                    style={{ animationDelay: `${delay}ms` }}
                  >
                    {step.href ? (
                      <a
                        href={step.href}
                        target="_blank"
                        rel="noreferrer"
                        className={`${ROW} ${align} transition-colors duration-150 hover:bg-accent ${FOCUS}`}
                      >
                        {content}
                      </a>
                    ) : onStepClick ? (
                      <button
                        type="button"
                        onClick={() => onStepClick(step, i)}
                        className={`${ROW} ${align} cursor-pointer transition-colors duration-150 hover:bg-accent ${FOCUS}`}
                      >
                        {content}
                      </button>
                    ) : (
                      <div className={`${ROW} ${align}`}>{content}</div>
                    )}
                  </li>
                );
              })}

              {more ? (
                <li className="px-1.5 pt-0.5 text-xs text-muted-foreground animate-[ui-fade-in_300ms_ease-out_both] motion-reduce:animate-none">
                  +{more} more
                </li>
              ) : null}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { AlertCircle, Ban, ChevronDown, RotateCcw, Wrench } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TOOL CALL: one tool invocation, from arguments to result
 *
 *   preparing  the model is still writing the arguments; the
 *              panel eases taller as each one arrives
 *   running    a spinner opens in and the label morphs to
 *              "Running"
 *   done       the spinner blurs into a check that draws itself
 *              and the run time rolls up from zero; the output
 *              rises in as the panel eases to fit it
 *   error      the label morphs to "Failed" in red, with the
 *              message and a retry
 *   denied     the user said no
 *
 * One status pill throughout: its icon slot opens and closes,
 * icons swap through a blur and the label morphs, so it never
 * swaps out. Arguments render as readable fields; nested
 * values as JSON.
 * Pass renderOutput to show a result your own way.
 * ───────────────────────────────────────────────────────── */

export type ToolCallStatus =
  "preparing" | "running" | "done" | "error" | "denied";

export interface ToolCallProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  /** The tool's name as the model calls it, e.g. "search_flights". */
  name: string;
  /** A human label, e.g. "Search flights". */
  title?: string;
  status: ToolCallStatus;
  /** Arguments, possibly partial while preparing. */
  input?: unknown;
  /** The result, once done. */
  output?: unknown;
  /** Render the result yourself, e.g. as a small card. */
  renderOutput?: (output: unknown) => React.ReactNode;
  errorText?: string;
  onRetry?: () => void;
  /** How long it ran (ms). */
  duration?: number;
  icon?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const LABELS: Record<ToolCallStatus, string> = {
  preparing: "Preparing",
  running: "Running",
  done: "Done",
  error: "Failed",
  denied: "Denied",
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${MORPH} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

/** The run time, in the unit that reads best; it rolls up from zero when the call has just finished. */
function Duration({ ms, rollIn }: { ms: number; rollIn: boolean }) {
  const from = rollIn ? 0 : undefined;
  if (ms < 1000)
    return <NumberRoll value={Math.round(ms)} suffix="ms" from={from} />;
  if (ms < 60000)
    return (
      <NumberRoll
        value={Math.round(ms / 100) / 10}
        format={ONE_DECIMAL}
        suffix="s"
        from={from}
      />
    );
  return (
    <>
      <NumberRoll value={Math.floor(ms / 60000)} suffix="m" from={from} />
      &nbsp;
      <NumberRoll
        value={Math.round((ms % 60000) / 1000)}
        suffix="s"
        from={from}
      />
    </>
  );
}
const ONE_DECIMAL = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function Value({ value }: { value: unknown }) {
  if (typeof value === "string")
    return <span className="break-words text-foreground">{value}</span>;
  if (typeof value === "number" || typeof value === "boolean" || value === null)
    return (
      <span className="font-mono text-[12px] text-foreground">
        {String(value)}
      </span>
    );
  return (
    <span className="break-all font-mono text-[11.5px] text-muted-foreground">
      {JSON.stringify(value)}
    </span>
  );
}

function Fields({ value }: { value: unknown }) {
  if (isPlainObject(value)) {
    const entries = Object.entries(value);
    if (entries.length === 0)
      return (
        <p className="text-[12.5px] text-muted-foreground">No arguments</p>
      );
    return (
      <dl className="grid grid-cols-[minmax(0,auto)_1fr] gap-x-4 gap-y-1.5 text-[12.5px]">
        {entries.map(([key, v]) => (
          <React.Fragment key={key}>
            <dt className="truncate font-mono text-[11.5px] leading-5 text-muted-foreground">
              {key}
            </dt>
            <dd className="min-w-0 leading-5">
              <Value value={v} />
            </dd>
          </React.Fragment>
        ))}
      </dl>
    );
  }
  if (typeof value === "string")
    return (
      <p className="whitespace-pre-wrap text-[12.5px] text-foreground">
        {value}
      </p>
    );
  return (
    <pre className="max-h-56 overflow-auto rounded-md bg-muted px-3 py-2 font-mono text-[11.5px] leading-5 text-foreground">
      {JSON.stringify(value, null, 2)}
    </pre>
  );
}

function Label({ children }: { children: React.ReactNode }) {
  return (
    <p className="mb-1.5 text-[11px] font-medium uppercase tracking-[0.06em] text-muted-foreground">
      {children}
    </p>
  );
}

export function ToolCall({
  name,
  title,
  status,
  input,
  output,
  renderOutput,
  errorText,
  onRetry,
  duration,
  icon,
  open,
  defaultOpen = false,
  onOpenChange,
  className = "",
  ...props
}: ToolCallProps) {
  const reduced = useReducedMotion();
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const [errorSeen, setErrorSeen] = React.useState(false);
  const panelId = React.useId();
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const [bodyHeight, setBodyHeight] = React.useState<number | null>(null);

  // Each time it finishes while you watch, the run time rolls up from zero (a finished call in history just sits).
  const [prevStatus, setPrevStatus] = React.useState(status);
  const [finishes, setFinishes] = React.useState(0);
  if (prevStatus !== status) {
    setPrevStatus(status);
    if (status === "done") setFinishes((n) => n + 1);
  }

  // The panel takes the height of what's in it, so arguments and output arriving ease it taller instead of jumping.
  React.useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el) return;
    const measure = () =>
      setBodyHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Failures open themselves once, so the reason is visible without a click.
  if (status === "error" && !errorSeen) {
    setErrorSeen(true);
    if (open === undefined) setOwnOpen(true);
  }

  const expanded = open ?? ownOpen;
  const toggle = () => {
    const next = !expanded;
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  const showTime = status === "done" && duration !== undefined;
  const icons: Partial<Record<ToolCallStatus, React.ReactNode>> = {
    // Spins only while running, so a hidden spinner never keeps the page busy.
    running: (
      <span
        className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${status === "running" ? "animate-spin" : ""}`}
      />
    ),
    done: (
      <span className="text-emerald-600 dark:text-emerald-400">
        <DrawnCheck drawn={status === "done"} reduced={reduced} />
      </span>
    ),
    error: <AlertCircle className="size-3.5" />,
    denied: <Ban className="size-3.5" />,
  };
  const badge = (
    <span
      className={`flex items-center text-[12px] transition-colors duration-300 ${status === "error" ? "font-medium text-red-500" : status === "preparing" ? "font-medium" : "text-muted-foreground"}`}
    >
      <span
        aria-hidden="true"
        className="relative flex h-3.5 shrink-0 items-center justify-center"
        style={{
          width: status === "preparing" ? 0 : 14,
          marginRight: status === "preparing" ? 0 : 5,
          transition: reduced
            ? "none"
            : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
        }}
      >
        {(Object.keys(icons) as ToolCallStatus[]).map((s) => (
          <span
            key={s}
            className="absolute inset-0 flex items-center justify-center"
            style={swap(s === status, reduced)}
          >
            {icons[s]}
          </span>
        ))}
      </span>
      <span className={status === "preparing" ? SHEEN : ""}>
        <TextMorph>{showTime ? "" : LABELS[status]}</TextMorph>
      </span>
      {duration !== undefined && (
        <span
          aria-hidden={!showTime || undefined}
          className="grid"
          style={{
            gridTemplateColumns: showTime ? "1fr" : "0fr",
            opacity: showTime ? 1 : 0,
            transition: reduced
              ? "none"
              : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
          }}
        >
          <span className="flex min-w-0 whitespace-nowrap tabular-nums [clip-path:inset(-4px_0)]">
            <Duration
              key={finishes}
              ms={duration}
              rollIn={finishes > 0 && !reduced}
            />
          </span>
        </span>
      )}
    </span>
  );

  return (
    <div
      className={`overflow-hidden rounded-xl border border-border bg-background ${className}`}
      {...props}
    >
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={panelId}
        onClick={toggle}
        className={`cursor-pointer flex w-full items-center gap-2.5 px-3 py-2.5 text-left transition-colors hover:bg-accent/60 ${FOCUS}`}
      >
        <span
          aria-hidden="true"
          className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground"
        >
          {icon ?? <Wrench className="size-3.5" />}
        </span>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-[13px] font-medium text-foreground">
            {title ?? name}
          </span>
          {title && (
            <span className="block truncate font-mono text-[11px] text-muted-foreground">
              {name}
            </span>
          )}
        </span>
        <span role="status" aria-live="polite" className="shrink-0">
          {badge}
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none ${expanded ? "rotate-180" : ""}`}
        />
      </button>

      <div
        id={panelId}
        inert={!expanded}
        className="overflow-hidden"
        style={{
          height: expanded ? (bodyHeight ?? "auto") : 0,
          opacity: expanded ? 1 : 0,
          transition:
            reduced || bodyHeight === null
              ? "none"
              : `height 420ms ${MORPH}, opacity 300ms ${MORPH}`,
        }}
      >
        <div ref={bodyRef}>
          <div className="flex flex-col gap-4 border-t border-border px-3 py-3">
            {input !== undefined && (
              <section>
                <Label>Input</Label>
                <Fields value={input} />
              </section>
            )}

            {status === "done" && output !== undefined && (
              <section className="animate-[ui-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
                <Label>Output</Label>
                {renderOutput ? (
                  renderOutput(output)
                ) : (
                  <Fields value={output} />
                )}
              </section>
            )}

            {status === "error" && (
              <section className="flex items-start justify-between gap-3 animate-[ui-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
                <p className="text-[12.5px] leading-5 text-red-500">
                  {errorText ?? "The tool failed."}
                </p>
                {onRetry && (
                  <button
                    type="button"
                    onClick={onRetry}
                    className={`cursor-pointer flex shrink-0 items-center gap-1.5 rounded-md border border-border px-2 py-1 text-[12px] font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`}
                  >
                    <RotateCcw aria-hidden="true" className="size-3" />
                    Retry
                  </button>
                )}
              </section>
            )}

            {status === "denied" && (
              <p className="text-[12.5px] text-muted-foreground">
                You declined this action, so it didn’t run.
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronDown, ChevronRight, Search } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * WEB RESEARCH: watch the agent search and read
 *
 *   searching  "Searching" shimmers; the live query types in
 *   reading    the label morphs to "Reading" and "7 sites"
 *              rolls up; each page drops its icon into the
 *              stack (the oldest folds away) while its title
 *              rises in underneath as the last one lifts off
 *   done       the line morphs into "3 searches · 9 sources":
 *              counts roll, words morph, the title row folds
 *              shut and a chevron opens in; open it for the list
 *   error      "Search failed", keeping whatever was found
 *   cancelled  "Stopped after 2 searches"
 *   trail      opened, each search is a row on a thin line trail
 *              with its count; a search on one site wears that
 *              site's mark, and the pages it found sit under it
 *              as overlapping marks that fold open into links
 *
 * Feed it the queries and sources as they arrive (tool calls
 * and source parts from the AI SDK); it animates the rest.
 * ───────────────────────────────────────────────────────── */

export type ResearchStatus =
  "searching" | "reading" | "done" | "error" | "cancelled";

export interface ResearchSource {
  url: string;
  title?: string;
  /** An icon URL; without one, a tinted monogram of the site. */
  favicon?: string;
  /** Which search found it (its index in queries), so the trail can group pages under their search. */
  query?: number;
}

export interface ResearchQuery {
  text: string;
  /** A search on one site, e.g. "threadly.com": the row wears that site's mark and reads "Searched Threadly for ...". */
  site?: string;
  /** An icon URL for that site. */
  siteIcon?: string;
  /** How many it found. */
  results?: number;
  /** The word after the count, e.g. "posts". Defaults to "results". */
  resultLabel?: string;
}

export interface WebResearchProps extends React.HTMLAttributes<HTMLDivElement> {
  status: ResearchStatus;
  /** Queries so far, as text or with their site and count; the last one is live while searching. */
  queries: (string | ResearchQuery)[];
  /** Pages read so far, in order. */
  sources: ResearchSource[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const STACK = 4;
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function hostname(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

function hue(text: string) {
  let h = 0;
  for (let i = 0; i < text.length; i++) h = (h * 31 + text.charCodeAt(i)) % 360;
  return h;
}

const asQuery = (q: string | ResearchQuery): ResearchQuery =>
  typeof q === "string" ? { text: q } : q;
const siteName = (site: string) => {
  const parts = hostname(`https://${site}`).split(".");
  const name = parts.length > 1 ? parts[parts.length - 2] : parts[0];
  return name.length <= 2
    ? name.toUpperCase()
    : name.charAt(0).toUpperCase() + name.slice(1);
};

const plural = (n: number, word: string) =>
  `${word}${n === 1 ? "" : /(s|sh|ch|x)$/.test(word) ? "es" : "s"}`;

function Favicon({
  source,
  className = "",
}: {
  source: ResearchSource;
  className?: string;
}) {
  const host = hostname(source.url);
  const [failed, setFailed] = React.useState(false);
  if (source.favicon && !failed) {
    return (
      <img
        src={source.favicon}
        alt=""
        onError={() => setFailed(true)}
        className={`rounded-full bg-background object-cover ${className}`}
      />
    );
  }
  const h = hue(host);
  return (
    <span
      aria-hidden="true"
      className={`flex items-center justify-center rounded-full text-[9.5px] font-semibold leading-none ${className}`}
      style={{
        background: `color-mix(in oklab, oklch(0.62 0.13 ${h}) 20%, var(--background))`,
        color: `oklch(0.5 0.12 ${h})`,
      }}
    >
      {host.charAt(0).toUpperCase()}
    </span>
  );
}

/** Types the newest query in, a few characters a frame; earlier text never re-types. */
function useTyped(text: string, active: boolean, reduced: boolean) {
  const [shown, setShown] = React.useState(text);
  React.useEffect(() => {
    if (!active || reduced) return;
    let i = 0;
    let frame = 0;
    const step = () => {
      i = Math.min(text.length, i + 2);
      setShown(text.slice(0, i));
      if (i < text.length) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [text, active, reduced]);
  return !active || reduced ? text : shown;
}

/** A piece of the line that opens out of nothing and folds back into it (width eases, content blurs in). */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid min-w-0 ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "180ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** One icon in the stack: drops in when it's new, folds away when it's pushed out by a newer one. */
function StackIcon({
  shown,
  first,
  enter,
  reduced,
  z,
  children,
}: {
  shown: boolean;
  first: boolean;
  enter: boolean;
  reduced: boolean;
  z: number;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      aria-hidden={!shown || undefined}
      className={`relative flex h-5 shrink-0 ${entering && !reduced ? "animate-[ui-drop-in_420ms_cubic-bezier(0.23,1,0.32,1)_backwards]" : ""}`}
      style={{
        zIndex: z,
        width: shown ? 20 : 0,
        marginLeft: shown && !first ? -6 : 0,
        opacity: shown ? 1 : 0,
        transform: shown ? "none" : "scale(0.6)",
        transition: reduced
          ? "none"
          : `width 420ms ${MORPH}, margin 420ms ${MORPH}, opacity 260ms ${MORPH}, transform 420ms ${MORPH}`,
      }}
    >
      <span className="flex size-5 shrink-0 overflow-hidden rounded-full ring-2 ring-background">
        {children}
      </span>
    </span>
  );
}

/** A one-line ticker: the new text rises in out of a blur while the last one lifts away. */
function Ticker({
  id,
  reduced,
  children,
}: {
  id: string;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [hasUpdated, setHasUpdated] = React.useState(false);
  const [current, setCurrent] = React.useState<{
    id: string;
    node: React.ReactNode;
  }>({ id, node: children });
  const [leaving, setLeaving] = React.useState<
    { id: string; node: React.ReactNode }[]
  >([]);
  if (current.id !== id) {
    if (!reduced)
      setLeaving((l) =>
        l.some((x) => x.id === current.id) ? l : [...l, current],
      );
    setCurrent({ id, node: children });
    if (!hasUpdated) setHasUpdated(true);
  }
  const done = React.useCallback(
    (leftId: string) => setLeaving((l) => l.filter((x) => x.id !== leftId)),
    [],
  );

  return (
    <span className="relative block h-4">
      {leaving.map((l) => (
        <Tick key={`out-${l.id}`} id={l.id} out onDone={done}>
          {l.node}
        </Tick>
      ))}
      <Tick key={id} id={id} enter={hasUpdated && !reduced}>
        {children}
      </Tick>
    </span>
  );
}

function Tick({
  id,
  out = false,
  enter = false,
  onDone,
  children,
}: {
  id: string;
  out?: boolean;
  enter?: boolean;
  onDone?: (id: string) => void;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const [entering] = React.useState(enter);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (out) {
      const animation = el.animate(
        [
          { opacity: 1, filter: "blur(0px)", transform: "none" },
          { opacity: 0, filter: "blur(4px)", transform: "translateY(-6px)" },
        ],
        { duration: 220, easing: MORPH, fill: "forwards" },
      );
      animation.onfinish = () => onDone?.(id);
      return () => animation.cancel();
    }
    if (!entering) return;
    const animation = el.animate(
      [
        { opacity: 0, filter: "blur(4px)", transform: "translateY(6px)" },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 380, easing: MORPH, delay: 60, fill: "backwards" },
    );
    return () => animation.cancel();
  }, [id, out, entering, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden={out || undefined}
      className="absolute inset-0 truncate text-[11.5px] text-muted-foreground/80"
    >
      {children}
    </span>
  );
}

function SourceLink({ source }: { source: ResearchSource }) {
  return (
    <a
      href={source.url}
      target="_blank"
      rel="noreferrer"
      className="flex h-7 items-center gap-2.5 rounded-lg px-1.5 outline-none transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/40"
    >
      <Favicon source={source} className="size-4 shrink-0" />
      <span className="min-w-0 flex-1 truncate text-[12.5px] text-foreground">
        {source.title ?? hostname(source.url)}
      </span>
      <span className="shrink-0 text-[11.5px] text-muted-foreground">
        {hostname(source.url)}
      </span>
    </a>
  );
}

/** The pages one search found: overlapping marks on a branch of the trail, folding open into links. */
function SourceGroup({
  sources,
  reduced,
}: {
  sources: ResearchSource[];
  reduced: boolean;
}) {
  const [open, setOpen] = React.useState(false);
  const listId = React.useId();
  const shown = sources.slice(0, 5);
  return (
    <div className="relative mb-1 ml-6">
      <span
        aria-hidden="true"
        className="absolute -left-3.5 -top-1 h-[13px] w-2.5 rounded-bl-[5px] border-b border-l border-border"
      />
      <button
        type="button"
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => setOpen((o) => !o)}
        className="cursor-pointer group flex h-6 items-center gap-2 rounded-md text-[12px] text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/40"
      >
        Sources
        <span className="flex items-center">
          {shown.map((src, i) => (
            <span
              key={src.url}
              className="flex size-4 overflow-hidden rounded-full ring-2 ring-background"
              style={{ marginLeft: i ? -5 : 0, zIndex: shown.length - i }}
            >
              <Favicon source={src} className="size-full" />
            </span>
          ))}
          {sources.length > shown.length && (
            <span className="ml-1 font-mono text-[10px]">
              +{sources.length - shown.length}
            </span>
          )}
        </span>
        <ChevronDown
          aria-hidden="true"
          className="size-3.5"
          style={{
            transform: open ? "rotate(180deg)" : "none",
            transition: reduced ? "none" : `transform 320ms ${EASE}`,
          }}
        />
        <span className="sr-only">({sources.length})</span>
      </button>
      <div
        id={listId}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          opacity: open ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${EASE}, opacity ${open ? "280ms" : "140ms"} ${EASE}`,
        }}
      >
        <ul className="-mx-1.5 min-h-0 overflow-hidden">
          {sources.map((src) => (
            <li key={src.url}>
              <SourceLink source={src} />
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export function WebResearch({
  status,
  queries,
  sources,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className = "",
  ...props
}: WebResearchProps) {
  const reduced = useReducedMotion();
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const open = openProp ?? ownOpen;
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  const working = status === "searching" || status === "reading";
  const query = queries.length ? asQuery(queries[queries.length - 1]).text : "";
  const typed = useTyped(query, status === "searching", reduced);
  const latest = sources[sources.length - 1];
  const extra = Math.max(0, sources.length - STACK);
  // Pages that don't say which search found them are listed after the trail.
  const ungrouped = sources.filter(
    (src) =>
      src.query === undefined || src.query < 0 || src.query >= queries.length,
  );
  const listId = React.useId();

  // Icons that arrive after the first paint drop in; the ones already there just sit.
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => {
    const timer = window.setTimeout(() => setMounted(true), 0);
    return () => window.clearTimeout(timer);
  }, []);

  // One line that rearranges itself: a label, then whichever counts this state needs.
  const label = {
    searching: "Searching",
    reading: "Reading",
    error: "Search failed",
    cancelled: "Stopped after",
    done: "",
  }[status];
  const showSearches = status === "done" || status === "cancelled";
  const showSources =
    sources.length > 0 &&
    (status === "reading" || status === "done" || status === "error");
  const showDot = showSources && (status === "done" || status === "error");
  const sourceWord =
    status === "reading"
      ? plural(sources.length, "site")
      : plural(sources.length, "source");

  const summary =
    status === "searching"
      ? `Searching for ${query}`
      : status === "reading"
        ? `Read ${sources.length} ${sourceWord}`
        : status === "error"
          ? `Search failed${sources.length ? `, ${sources.length} ${sourceWord}` : ""}`
          : status === "cancelled"
            ? `Stopped after ${queries.length} ${plural(queries.length, "search")}`
            : `Done: ${queries.length} ${plural(queries.length, "search")}, ${sources.length} ${sourceWord}`;

  return (
    <div className={`w-full ${className}`} {...props}>
      {/* The same row from first search to final summary, so every piece of it can morph; it becomes a button once there's a list to open. */}
      <button
        type="button"
        disabled={working}
        aria-expanded={working ? undefined : open}
        aria-controls={working ? undefined : listId}
        onClick={() => setOpen(!open)}
        className="group flex min-h-9 w-full items-center gap-2.5 rounded-lg py-1 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/40 disabled:cursor-default"
      >
        <span
          aria-hidden="true"
          className="relative flex h-5 shrink-0 items-center"
        >
          <StackIcon
            shown={sources.length === 0}
            first
            enter={false}
            reduced={reduced}
            z={0}
          >
            <span className="flex size-full items-center justify-center bg-muted text-muted-foreground">
              <Search
                className={`size-3 ${working ? "animate-[ui-breathe_1.6s_ease-in-out_infinite] motion-reduce:animate-none" : ""}`}
                strokeWidth={2.2}
              />
            </span>
          </StackIcon>
          {sources.map((s, i) => (
            <StackIcon
              key={s.url}
              shown={i >= sources.length - STACK}
              first={i === Math.max(0, sources.length - STACK)}
              enter={mounted && working}
              reduced={reduced}
              z={i + 1}
            >
              <Favicon source={s} className="size-full" />
            </StackIcon>
          ))}
          <Reveal
            show={extra > 0}
            reduced={reduced}
            className="relative z-[999]"
          >
            <span className="ml-[-6px] flex h-5 min-w-5 items-center justify-center rounded-full bg-muted px-1 font-mono text-[9.5px] text-muted-foreground ring-2 ring-background">
              <NumberRoll value={extra} prefix="+" duration={600} />
            </span>
          </Reveal>
        </span>

        <span className="min-w-0 flex-1 text-left">
          <span
            className={`flex min-w-0 items-center text-[13px] leading-5 transition-colors duration-300 ${status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
          >
            <span
              className={`shrink-0 font-medium transition-colors duration-300 ${working ? SHEEN : ""}`}
            >
              <TextMorph>{label}</TextMorph>
            </span>
            <Reveal show={showSearches} reduced={reduced} className="shrink-0">
              <span
                className="inline-flex items-baseline transition-[padding] duration-500"
                style={{
                  paddingLeft: label ? 5 : 0,
                  transitionTimingFunction: MORPH,
                }}
              >
                <NumberRoll value={queries.length} duration={700} />
                &nbsp;
                <TextMorph>{plural(queries.length, "search")}</TextMorph>
              </span>
            </Reveal>
            <Reveal show={showDot} reduced={reduced} className="shrink-0">
              <span className="px-1.5 opacity-60">·</span>
            </Reveal>
            <Reveal show={showSources} reduced={reduced} className="shrink-0">
              <span
                className="inline-flex items-baseline transition-[padding] duration-500"
                style={{
                  paddingLeft: showDot ? 0 : 5,
                  transitionTimingFunction: MORPH,
                }}
              >
                <NumberRoll value={sources.length} duration={700} />
                &nbsp;
                <TextMorph>{sourceWord}</TextMorph>
              </span>
            </Reveal>
            <Reveal
              show={status === "searching" && Boolean(query)}
              reduced={reduced}
              className="shrink"
            >
              <span className="block truncate pl-1.5">“{typed}”</span>
            </Reveal>
          </span>
          {/* The page being read; the row folds shut when the work is done. */}
          <span
            aria-hidden={!working || undefined}
            className="grid"
            style={{
              gridTemplateRows: working && latest ? "1fr" : "0fr",
              opacity: working && latest ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-rows 420ms ${MORPH}, opacity 260ms ${MORPH}`,
            }}
          >
            <span className="min-h-0 overflow-hidden">
              <span className="block pt-0.5">
                {latest && (
                  <Ticker id={latest.url} reduced={reduced}>
                    {latest.title ?? hostname(latest.url)}{" "}
                    <span className="text-muted-foreground/60">
                      · {hostname(latest.url)}
                    </span>
                  </Ticker>
                )}
              </span>
            </span>
          </span>
        </span>

        <Reveal show={!working} reduced={reduced} className="shrink-0">
          <ChevronRight
            aria-hidden="true"
            className="size-3.5 text-muted-foreground transition-transform duration-300 group-hover:text-foreground motion-reduce:transition-none"
            style={{
              transform: open ? "rotate(90deg)" : "none",
              transitionTimingFunction: EASE,
            }}
          />
        </Reveal>
      </button>
      {/* Outside the button, so the button's name stays its visible text. */}
      <span role="status" aria-live="polite" className="sr-only">
        {summary}
      </span>

      <div
        id={listId}
        inert={!open || working}
        className="grid"
        style={{
          gridTemplateRows: open && !working ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 380ms ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="ml-[9px] mt-1 pl-[19px]">
            {queries.length > 0 && (
              <ul className="pb-1">
                {queries.map((raw, i) => {
                  const q = asQuery(raw);
                  const found = sources.filter((src) => src.query === i);
                  const last =
                    i === queries.length - 1 && ungrouped.length === 0;
                  return (
                    <li key={i} className="relative">
                      {/* The trail: a thin line down the left, a short branch to each search. */}
                      <span
                        aria-hidden="true"
                        className="absolute -left-[19px] top-0 w-px bg-border"
                        style={last ? { height: 15 } : { bottom: 0 }}
                      />
                      <span
                        aria-hidden="true"
                        className="absolute -left-[19px] top-[15px] h-px w-3 bg-border"
                      />
                      <div className="flex items-start gap-2 py-1.5 text-[12.5px] leading-[18px] text-muted-foreground">
                        <span className="mt-px flex size-4 shrink-0 items-center justify-center">
                          {q.site ? (
                            <Favicon
                              source={{
                                url: `https://${q.site}`,
                                favicon: q.siteIcon,
                              }}
                              className="size-4"
                            />
                          ) : (
                            <Search
                              aria-hidden="true"
                              className="size-3.5"
                              strokeWidth={2.1}
                            />
                          )}
                        </span>
                        <span className="min-w-0 flex-1 text-foreground/85">
                          {q.site ? (
                            <>
                              Searched {siteName(q.site)} for{" "}
                              <span className="font-mono text-[11.5px] text-muted-foreground">
                                {q.text}
                              </span>
                            </>
                          ) : (
                            q.text
                          )}
                        </span>
                        {q.results != null && (
                          <span className="shrink-0 whitespace-nowrap tabular-nums">
                            {q.results}{" "}
                            {q.resultLabel ?? plural(q.results, "result")}
                          </span>
                        )}
                      </div>
                      {found.length > 0 && (
                        <SourceGroup sources={found} reduced={reduced} />
                      )}
                    </li>
                  );
                })}
              </ul>
            )}
            {ungrouped.length > 0 && (
              <div
                className={
                  queries.length
                    ? "border-t border-border/60 pb-1 pt-1.5"
                    : "pb-1"
                }
              >
                <ul className="-mx-1.5 max-h-80 overflow-y-auto overflow-x-hidden px-1.5 [scrollbar-color:var(--border)_transparent] [scrollbar-width:thin]">
                  {ungrouped.map((src) => (
                    <li key={src.url}>
                      <SourceLink source={src} />
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

